#!/usr/bin/env bash
set -uo pipefail

mkdir -p artifacts

collect_diagnostics() {
  if [[ -d "$HOME/.maestro/tests" ]]; then
    cp -R "$HOME/.maestro/tests" artifacts/maestro-debug 2>/dev/null || true
  fi
  adb logcat -d > artifacts/android-logcat.txt 2>&1 || true
  adb shell uiautomator dump /sdcard/window.xml >/dev/null 2>&1 || true
  adb pull /sdcard/window.xml artifacts/android-ui.xml >/dev/null 2>&1 || true
  adb exec-out screencap -p > artifacts/android-screen.png 2>/dev/null || true
  # Collect only PDFs generated by synthetic tests inside this disposable emulator.
  if adb root > artifacts/adb-root.txt 2>&1 && timeout 15 adb wait-for-device; then
    mkdir -p artifacts/generated-pdfs
    adb pull /data/user/0/com.hamza.app/cache/Print artifacts/generated-pdfs/ > artifacts/pdf-copy.txt 2>&1 || true
  fi
}

apk_path="$(find dist/apk -type f -name '*.apk' -print -quit)"
if [[ -z "$apk_path" ]]; then
  echo "No APK was downloaded."
  exit 2
fi

adb install "$apk_path"
install_status=$?
if [[ $install_status -ne 0 ]]; then
  collect_diagnostics
  exit "$install_status"
fi

curl -Ls "https://get.maestro.mobile.dev" | bash
install_status=$?
if [[ $install_status -ne 0 ]]; then
  collect_diagnostics
  exit "$install_status"
fi

"$HOME/.maestro/bin/maestro" --version
"$HOME/.maestro/bin/maestro" test "${MAESTRO_FLOW:-.maestro}"
smoke_status=$?
collect_diagnostics
if [[ "$smoke_status" -eq 0 && ( "${MAESTRO_FLOW:-}" == ".maestro/pos-sale.yaml" || "${MAESTRO_FLOW:-}" == ".maestro/purchase-return.yaml" ) ]]; then
  pdf_path="$(find artifacts/generated-pdfs/Print -maxdepth 1 -type f -name '*.pdf' -print -quit 2>/dev/null || true)"
  if [[ -z "$pdf_path" ]]; then
    echo "POS checkout did not generate a PDF receipt."
    smoke_status=1
  else
    echo "POS checkout generated PDF receipt: $(basename "$pdf_path")"
  fi
fi
exit "$smoke_status"
